import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {alpha} rounds are held. For each positive integer n and real numbers a_1, a_2, ..., a_n chosen from the interval [-{neg_bound}, {pos_bound}], let S = a_1 + a_2 + ... + a_n. Define F(n) to be the maximum possible value of sum_{i=1}^n | (S - {t_param}·a_i)/n - a_i | over all such choices of a_1, ..., a_n. Compute the value of sum_{k=1}^{alpha} k·F(k).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Try several times to produce a challenging, valid assignment
for _ in range(64):
    alpha = rng.randint(180, 420)
    neg_bound = rng.randint(1, 6)
    pos_bound = rng.randint(1, 6)
    if pos_bound == neg_bound:
        continue
    t_param = rng.randint(2, 9)
    # Evaluate difficulty: ensure interior maximizers occur for multiple n
    interior_count = 0
    for n in range(1, alpha + 1):
        max_val = None
        best_m = None
        A = neg_bound
        B = pos_bound
        t = t_param
        for m in range(0, n + 1):
            v = m * abs((A + B) * (m - n) - t * B) + (n - m) * abs(m * (A + B) + t * A)
            if (max_val is None) or (v > max_val):
                max_val = v
                best_m = m
        if 0 < best_m < n:
            interior_count += 1
    # Require a reasonable number of interior maxima to avoid trivial instances
    if interior_count >= max(5, alpha // 12):
        return {'alpha': alpha, 'neg_bound': neg_bound, 'pos_bound': pos_bound, 't_param': t_param}
# Fallback to a known nontrivial instance
return {'alpha': 275, 'neg_bound': 1, 'pos_bound': 3, 't_param': 4}

    def verifier(assign):
# Validate presence and types
try:
    alpha = int(assign['alpha'])
    neg_bound = int(assign['neg_bound'])
    pos_bound = int(assign['pos_bound'])
    t_param = int(assign['t_param'])
except Exception:
    # Missing or non-integer fields
    return (False, None)
# Domain checks
if alpha <= 0 or neg_bound <= 0 or pos_bound <= 0 or t_param <= 0:
    return (False, None)  # invalid ranges
if pos_bound == neg_bound:
    return (False, None)  # disallow symmetric [-A, A] to ensure harder-than-seed asymmetry
# Compute answer using the extremal reduction proof:
# For each n, F(n) = (1/n) * max_{0<=m<=n} [ m*| (A+B)(m-n) - t*B | + (n-m)*| m(A+B) + t*A | ], with A=neg_bound, B=pos_bound, t=t_param
total = 0
interior_count = 0
A = neg_bound
B = pos_bound
t = t_param
for n in range(1, alpha + 1):
    max_val = None
    best_m = None
    for m in range(0, n + 1):
        v = m * abs((A + B) * (m - n) - t * B) + (n - m) * abs(m * (A + B) + t * A)
        if (max_val is None) or (v > max_val):
            max_val = v
            best_m = m
    # Since F(n) = max_val / n, the summand n * F(n) equals max_val (an integer for integer A,B,t)
    total += max_val
    if 0 < best_m < n:
        interior_count += 1
# Difficulty enforcement: ensure multiple n have interior maximizers
if interior_count < max(5, alpha // 12):
    # Too many cases trivial at endpoints only; reject to maintain challenge
    return (False, None)
return (True, total)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

